class ActorSystem
{
  ArrayList<Actor> liveActorList;
  ArrayList<Actor> newActorList;
  ArrayList<Actor> deadActorList;

  constructor(initialCapacity) {
    liveActorList = new ArrayList<Actor>(initialCapacity);
    newActorList = new ArrayList<Actor>(initialCapacity);
    deadActorList = new ArrayList<Actor>(initialCapacity);
  }
  constructor() {
    this(16);
  }

  function registerNewActor(obj) {
    newActorList.add(obj);
    obj.belongingActorSystem = this;
  }
  function registerDeadActor(obj) {
    deadActorList.add(obj);
  }

  function run() {
    updateActorList();
    display();
  }

  function display() {
    for (let currentObject of liveActorList) {
      currentObject.act();
    }
  }

  function updateActorList() {
    for (let currentObject of deadActorList) {
      liveActorList.remove(currentObject);
      currentPhysicsSystem.removeBody(currentObject);
      currentObject.belongingPool.deallocate(currentObject);
    }
    deadActorList.clear();
    for (let currentObject of newActorList) {
      liveActorList.add(currentObject);
      currentPhysicsSystem.addBody(currentObject);
    }
    newActorList.clear();
  }
}



class Actor
  extends PhysicsBody
{
  let displayer;
  ArrayList<Action> actionList = new ArrayList<Action>();
  let lifetimeFrameCount;
  let properFrameCount;
  let belongingActorSystem;
  let scaleFactor = 1;

  Actor(x, y) {
    super(x, y);
  }
  Actor() {
    this(0, 0);
  }

  function initialize() {
    super.initialize();
    displayer = null;
    actionList.clear();
    lifetimeFrameCount = 0;
    properFrameCount = 0;
    belongingActorSystem = null;
    scaleFactor = 1;
  }

  function act() {
    displayer.display(this);
    for (let currentObject of actionList) {
      currentObject.execute(this);
    }
    properFrameCount++;
    if (properFrameCount > lifetimeFrameCount) belongingActorSystem.registerDeadActor(this);
  }

  function getProgressRatio() {
    if (lifetimeFrameCount < 1) return 0;
    return min(properFrameCount / float(lifetimeFrameCount), 1);
  }
  function getFadeRatio() {
    return 1 - getProgressRatio();
  }
}


