abstract class FogBackground extends PreRenderedBackground {
  constructor(x, y, baseColor, baseBrightness, noiseBrightness, noiseIncrement) {
    super(x, y);
    createFog(x, y, baseColor, baseBrightness, noiseBrightness, noiseIncrement);
  }
  constructor(x, y) {
    this(x, y, color(0, 0, 0), 70, 30, 0.01);
  }
  constructor() {
    this(width, height);
  }

  function createFog(x, y, baseColor, baseBrightness, noiseBrightness, noiseIncrement) {
    graphics.loadPixels();
    let xoff = 0.0;
    for (xp = 0; xp < x; xp++) {
      xoff += noiseIncrement;
      let yoff = 0.0;
      for (yp = 0; yp < y; yp++) {
        yoff += noiseIncrement;
        let bright = constrain(baseBrightness + noise(xoff, yoff) * noiseBrightness, 0, 100);
        graphics.pixels[xp + yp * x] = getPixelColor(baseColor, bright);
      }
    }
    graphics.updatePixels();
  }

  abstract getPixelColor(baseColor, bright);
}

