class GradationBackground extends PreRenderedBackground {
  constructor(x, y, aboveColor, belowColor, gradient) {
    super(x, y);
    graphics.loadPixels();
    for (xp = 0; xp < x; xp++) {
      for (yp = 0; yp < y; yp++) {
        graphics.pixels[xp + yp * x] = lerpColor(aboveColor, belowColor, pow(float(yp) / y, gradient));
      }
    }
    graphics.updatePixels();
  }
  constructor(x, y) {
    this(x, y, color(0, 0, 100), color(240, 20, 100), 1);
  }
  constructor() {
    this(width, height);
  }
}

