// let defined actions

class BurnFireAction extends FireAction {
  burningTimeRatio = 0.6;

  constructor(b) {
    super(b);
  }

  function execute(parentActor) {
    if (parentActor.getProgressRatio() > burningTimeRatio) return;
    let burnRatio = (burningTimeRatio - parentActor.getProgressRatio()) / burningTimeRatio;

    let xOff = 3 * sin(3 * frameCount * TWO_PI / IDEAL_FRAME_RATE) * burnRatio;
    var newActor = builder.build(parentActor.xPosition + xOff, parentActor.yPosition, parentActor.xVelocity - xOff, parentActor.yVelocity);
    newActor.scaleFactor = burnRatio;
    parentActor.belongingActorSystem.registerNewActor(newActor);
  }
}

class ExplodeFireAction extends FireAction {
  ArrayList<ActorDisplayer> displayerCandidateList = new ArrayList<ActorDisplayer>();

  constructor(b) {
    super(b);
  }

  function execute(parentActor) {
    if(parentActor.properFrameCount == int(parentActor.lifetimeFrameCount * 0.99)) {
      explode(parentActor, 400 / IDEAL_FRAME_RATE);
    }
    if(parentActor.properFrameCount == parentActor.lifetimeFrameCount) {
      explode(parentActor, 150 / IDEAL_FRAME_RATE);
    }
  }

  function explode(parentActor, initialSpeed) {
    // let the displayer of the child (GunpowderBall) randomly for the purpose of let variation
    let gunpowderBallDisplayer = displayerCandidateList.get(int(random(displayerCandidateList.size())));

    let anglePartitionCount = 15;
    let unitAngle = TWO_PI / anglePartitionCount;
    for (i = 0; i < anglePartitionCount; i++) {
      for (k = 0; k < anglePartitionCount; k++) {
        var newActor = builder.build();
        newActor.displayer = gunpowderBallDisplayer;
        newActor.xPosition = parentActor.xPosition;
        newActor.yPosition = parentActor.yPosition;

        let theta = (i + random(0.5)) * unitAngle;
        let phi = (k + random(0.5)) * unitAngle;
        newActor.xVelocity = initialSpeed * cos(theta) * cos(phi);
        newActor.yVelocity = initialSpeed * cos(theta) * sin(phi);

        parentActor.belongingActorSystem.registerNewActor(newActor);
      }
    }
  }
}

class LeaveGunpowderFireAction
  extends FireAction
{
  LeaveGunpowderFireAction(b) {
    super(b);
  }

  function execute(parentActor) {
    if (random(1) < calculateFireProbability(parentActor)) {
      var newActor = builder.build(parentActor.xPosition, parentActor.yPosition, parentActor.xVelocity, parentActor.yVelocity);
      newActor.displayer = parentActor.displayer;
      parentActor.belongingActorSystem.registerNewActor(newActor);
    }
  }

  function calculateFireProbability(parentActor) {
    if (parentActor.getProgressRatio() < 0.2) return 0.1 * parentActor.getProgressRatio() * 5;
    return 0.1 * parentActor.getFadeRatio();
  }
}



// let defined displayers

class FlashActorDisplayer extends ActorDisplayer {
  constructor(img) {
    super(img);
  }

  function display(parentActor) {
    if(random(1) < calculateDisplayProbability(parentActor)) {
      image(actorImage, parentActor.xPosition, parentActor.yPosition);
    }
  }

  calculateDisplayProbability(parentActor) {
    let fadeRatio = parentActor.getFadeRatio();
    if (fadeRatio > 0.5) return 0.9;
    return fadeRatio * 2 * 0.9;
  }
}

class ShrinkActorDisplayer extends ActorDisplayer {
  displayTimeRatio = 0.8;

  constructor(img) {
    super(img);
  }

  function display(parentActor) {
    if(parentActor.getProgressRatio() > displayTimeRatio) return;
    let shrinkRatio = (displayTimeRatio - parentActor.getProgressRatio()) / displayTimeRatio;

    pushMatrix();
    translate(parentActor.xPosition, parentActor.yPosition);
    scale(parentActor.scaleFactor * pow(shrinkRatio, 0.5));
    image(actorImage, 0, 0);
    popMatrix();
  }
}

class FadeActorDisplayer extends ActorDisplayer {
  constructor(img) {
    super(img);
  }

  function display(parentActor) {
    tint(color(0, 0, 100, 100 * pow(parentActor.getFadeRatio(), 0.5)));
    image(actorImage, parentActor.xPosition, parentActor.yPosition);
    noTint();
  }
}

