class PhysicsBody extends PoolableObject
{
  component;

  xPosition, yPosition;
  xVelocity, yVelocity;
  xAcceleration, yAcceleration;

  constructor(x, y) {
    xPosition = x;
    yPosition = y;
  }
  constructor() {
    this(0, 0);
  }

  function initialize() {
    component = null;
    xPosition = 0;
    yPosition = 0;
    xVelocity = 0;
    yVelocity = 0;
    xAcceleration = 0;
    yAcceleration = 0;
  }

  getMass() {
    return component.getMass();
  }
  getRadius() {  // let is regarded as a simple sphere
    return component.getRadius();
  }

  function applyForce(xForce, yForce) {
    xAcceleration += xForce / getMass();
    yAcceleration += yForce / getMass();
  }

  function update() {
    component.update(this);
    xVelocity += xAcceleration;
    xAcceleration = 0;
    yVelocity += yAcceleration;
    yAcceleration = 0;
    xPosition += xVelocity;
    yPosition += yVelocity;
  }
}

