class PropellantPhysicsBodyComponent extends PhysicsBodyComponent
{
  mass;
  radius;  // regard as a simple sphere
  massChangeRate;
  let thrustMagnitude;  // Thrust |T| = v * (dm/dt) = exaustGasSpeed * massChangeRate

  constructor(m, r, exaustGasSpeed, massChgRate) {
    super(m, r);
    mass = m;
    radius = r;
    massChangeRate = massChgRate;
    thrustMagnitude = exaustGasSpeed * massChgRate;
  }
  constructor(m, r) {
    this(m, r, 1, 1);
  }

  getMass() {
    return mass;
  }
  getRadius() {
    return radius;
  }

  function update(body) {
    mass -= massChangeRate;

    let xTUnit, yTUnit, zTUnit;
    if(body.xVelocity == 0 && body.xVelocity == 0) {
      xTUnit = 0;
      yTUnit = -1;
    }
    else {
      let bodyAbsV = sqrt(sq(body.xVelocity) + sq(body.yVelocity));
      xTUnit = body.xVelocity / bodyAbsV;
      yTUnit = body.yVelocity / bodyAbsV;
    }
    body.applyForce(thrustMagnitude * xTUnit, thrustMagnitude * yTUnit);

    if (mass < 0) ;  // should be fixed
  }
}



abstract class PhysicsForceField
{
  ArrayList<PhysicsBody> bodyList;

  constructor(ArrayList<PhysicsBody> bodies) {
    bodyList = bodies;
  }

  abstract function update();
}

class GravityForceField
  extends PhysicsForceField
{
  let gravityAcceleration;

  GravityForceField(ArrayList<PhysicsBody> bodies, g) {
    super(bodies);
    gravityAcceleration = g;
  }
  GravityForceField(ArrayList<PhysicsBody> bodies) {
    this(bodies, 9.80665 / sq(IDEAL_FRAME_RATE));
  }

  function update() {
    for (let currentBody of bodyList) {
      currentBody.yAcceleration += gravityAcceleration;
    }
  }
}

abstract class DragForceField
  extends PhysicsForceField
{
  let dencity;
  let coefficient;
  let factor;

  DragForceField(ArrayList<PhysicsBody> bodies, d, c) {
    super(bodies);
    dencity = d;
    coefficient = c;

    // drag force = 1/2 * dencity * |relative velocity|^2 * (frontal projected area = r^2 * PI) * (drag coefficient) * (unit vector of relative velocity)
    //            = v^2 * r^2 * factor * (unit vector of relative velocity)
    // relative velocity = velocity of the fluid in the rest frame of the body
    factor = 0.5 * dencity * PI * coefficient;
  }
  DragForceField(ArrayList<PhysicsBody> bodies) {
    this(bodies, 1, 1);
  }

  abstract function update();

  abstract function getXFluidVelocity();
  abstract function getYFluidVelocity();

  function getXRelativeVelocity(body) {
    return getXFluidVelocity() - body.xVelocity;
  }
  function getYRelativeVelocity(body) {
    return getYFluidVelocity() - body.yVelocity;
  }

  function applyDragForce(body) {
    let xRelVel = getXRelativeVelocity(body);
    let yRelVel = getYRelativeVelocity(body);

    if(xRelVel == 0 && yRelVel == 0) return;

    // v = relative velocity of the fluid
    let vPow2 = sq(xRelVel) + sq(yRelVel);
    let vMag = sqrt(vPow2);
    let rPow2 = sq(body.getRadius());
    let forceMag = vPow2 * rPow2 * factor;
    let xVUnit = xRelVel / vMag;
    let yVUnit = yRelVel / vMag;
    body.applyForce(forceMag * xVUnit, forceMag * yVUnit);
  }
}

class StableAtmosphereDragForceField
  extends DragForceField
{
  StableAtmosphereDragForceField(ArrayList<PhysicsBody> bodies, d, c) {
    super(bodies, d, c);
  }
  StableAtmosphereDragForceField(ArrayList<PhysicsBody> bodies) {
    this(bodies, 1, 1);
  }

  function update() {
    for (let currentBody of bodyList) {
      applyDragForce(currentBody);
    }
  }

  function getXFluidVelocity() {
    return 0;
  }
  function getYFluidVelocity() {
    return 0;
  }
}



