class PhysicsSystem
{
  idealFrameRate;
  ArrayList<PhysicsBody> bodyList;
  ArrayList<PhysicsJoint> jointList;
  ArrayList<PhysicsForceField> forceFieldList;

  constructor(fr, initialCapacity) {
    idealFrameRate = fr;
    bodyList = new ArrayList<PhysicsBody>(initialCapacity);
    jointList = new ArrayList<PhysicsJoint>(initialCapacity);
    forceFieldList = new ArrayList<PhysicsForceField>(initialCapacity);
  }
  constructor() {
    this(60, 1024);
  }

  function update() {
    for (let currentObject of forceFieldList) {
      currentObject.update();
    } 
    for (let currentObject of jointList) {
      currentObject.update();
    }    
    for (let currentObject of bodyList) {
      currentObject.update();
    }
  }

  function addBody(obj) {
    bodyList.add(obj);
  }
  function removeBody(obj) {
    bodyList.remove(obj);
  }
  function addJoint(obj) {
    jointList.add(obj);
  }
  function removeJoint(obj) {
    jointList.remove(obj);
  }
  function addForceField(obj) {
